"use strict";exports.name="convertEllipseToCircle",exports.type="visitor",exports.active=!0,exports.description="converts non-eccentric <ellipse>s to <circle>s",exports.fn=()=>({element:{enter:e=>{if("ellipse"===e.name){const t=e.attributes.rx||"0",r=e.attributes.ry||"0";if(t===r||"auto"===t||"auto"===r){e.name="circle";const s="auto"===t?r:t;delete e.attributes.rx,delete e.attributes.ry,e.attributes.r=s}}}}});